{
  "decision-interline-through-ticket-change": "WITH eligible_rules AS (SELECT offer_id, MAX(fee_cents) AS change_fee_cents FROM coupon_rule GROUP BY offer_id HAVING MIN(change_allowed) = 1), priced AS (SELECT o.offer_id, MAX(0, o.through_cents - t.original_cents) AS fare_increase_cents, r.change_fee_cents FROM offer AS o JOIN ticket AS t ON t.ticket_id = o.ticket_id JOIN eligible_rules AS r ON r.offer_id = o.offer_id WHERE t.ticket_id = 'T') SELECT offer_id, fare_increase_cents, change_fee_cents, fare_increase_cents + change_fee_cents AS due_cents FROM priced ORDER BY due_cents, offer_id COLLATE BINARY LIMIT 1",
  "decision-interval-energy-netting": "WITH intervals AS (SELECT day_no, SUM(deviation_kwh) AS net_kwh FROM reading GROUP BY day_no, minute_no / 15) SELECT day_no, SUM(CASE WHEN net_kwh < 0 THEN -5 * net_kwh ELSE 2 * net_kwh END) AS penalty_cents FROM intervals GROUP BY day_no ORDER BY day_no",
  "decision-inventory-step-up-by-production-stage": "WITH quotes AS (SELECT p.*, ROW_NUMBER() OVER (PARTITION BY item_code, quote_kind ORDER BY quote_day DESC, source_id COLLATE BINARY ASC) AS rn FROM price_evidence AS p WHERE quote_day <= '2026-03-31'), valued AS (SELECT l.lot_id, q.source_id, l.qty * CASE WHEN l.stage_code = 'RAW' THEN q.unit_cents ELSE q.unit_cents - COALESCE(l.sell_cost, 0) - COALESCE(l.sell_profit, 0) - l.finish_cost - l.finish_profit END AS fair_value_cents, l.qty * l.book_unit AS carrying_cents FROM stock_lot AS l JOIN quotes AS q ON q.item_code = l.item_code AND q.quote_kind = CASE WHEN l.stage_code = 'RAW' THEN 'REPLACE' ELSE 'SELL' END AND q.rn = 1) SELECT lot_id, source_id, fair_value_cents, fair_value_cents - carrying_cents AS adjustment_cents FROM valued ORDER BY lot_id COLLATE BINARY",
  "decision-isolate-main-with-overlapping-outages": "SELECT e.valve_code AS east_valve, w.valve_code AS west_valve, (SELECT COALESCE(SUM(b.connections), 0) FROM service_block AS b WHERE b.block_code IN (SELECT v.block_code FROM valve_effect AS v WHERE v.valve_code IN (e.valve_code, w.valve_code))) AS connections_out, e.turn_minutes + w.turn_minutes AS work_minutes FROM valve_option AS e CROSS JOIN valve_option AS w WHERE e.feed_path = 'east' AND w.feed_path = 'west' ORDER BY connections_out, work_minutes, east_valve COLLATE BINARY, west_valve COLLATE BINARY LIMIT 1"
}
